#define _YY_GLSLES_ 1
//
// Simple passthrough fragment shader
//
varying vec2 v_vTexcoord;
varying vec4 v_vColour;
uniform float iTime;
uniform vec2 iResolution;

const float tau = 6.28318530717958647692;
const float PHI = 1.61803398874989484820459 * 00000.1; // Golden Ratio   
const float PI  = 3.14159265358979323846264 * 00000.1; // PI
const float SQ2 = 1.41421356237309504880169 * 10000.0; // Square Root of Two

// Gamma correction
//const float GAMMA = 2.2;
#define GAMMA (2.2)

vec3 ToLinear( vec3 col )
{
	// simulate a monitor, converting colour values into light values
	return pow( col, vec3(GAMMA) );
}

vec3 ToGamma( vec3 col )
{
	// convert back into colour values, so the correct light will come out of the monitor
	return pow( col, vec3(1.0/GAMMA) );
}

vec4 Noise( vec2 X )
{
	//return texture( iChannel0, (vec2(x)+0.5)/256.0, -100.0 );
	return vec4(fract(tan(distance(X*(7.7+PHI), vec2(PHI, PI)))*SQ2));
}

void main()
{

	//void mainImage( out vec4 fragColor, in vec2 fragCoord )
	//{
		vec3 ray;
		ray.xy = 2.0*(v_vTexcoord.xy-iResolution.xy*.5)/iResolution.x;
		ray.z = 1.0;

		float offset = iTime*0.333;	
		float speed2 = (cos(offset)+1.0)*2.0;
		float speed = speed2+.1;
		offset += sin(offset)*.96;
		offset *= 2.0;
	
	
		vec3 col = vec3(0);
	
		vec3 stp = ray/max(abs(ray.x),abs(ray.y));
	
		vec3 pos = 2.0*stp+.5;
		for ( int i=0; i < 10; i++ )
		{
